%dw 2.0
output application/json
var generatedId = "AC-SIA-BA-001"
var paymentMethodId = (payload.paymentMethod.id default payload.defaultPaymentMethod.id default "PM-BANK-001") as String
var paymentMethod = {
  "@type": "PaymentMethodRef",
  id: paymentMethodId,
  href: payload.paymentMethod.href default payload.defaultPaymentMethod.href default ("https://host:port/tmf-api/paymentMethods/v5/paymentMethod/" ++ paymentMethodId),
  name: payload.paymentMethod.name default payload.defaultPaymentMethod.name default "Bank Transfer"
}
var incomingCycle = payload.billingCycleSpecification default {}
var cycleSpecification = {
  "@type": "BillingCycleSpecification",
  id: incomingCycle.id default "BCS-MONTHLY-01",
  href: incomingCycle.href default "https://host:port/tmf-api/accountManagement/v5/billingCycleSpecification/BCS-MONTHLY-01",
  name: incomingCycle.name default "Monthly billing",
  frequency: incomingCycle.frequency default "monthly",
  dateShift: incomingCycle.dateShift default incomingCycle.billingDateShift default 0
}
var normalizedRelatedParty = if (sizeOf(payload.relatedParty default []) > 0)
  (payload.relatedParty default []) map (rp) -> {
    "@type": "RelatedPartyRefOrRelatedPartyRoleRef",
    role: rp.role default "billReceiver",
    partyOrPartyRole: {
      "@type": "PartyRefOrPartyRoleRef",
      "@referredType": rp."@referredType" default "Organization",
      id: rp.id default "ORG-ALPHA-001",
      href: rp.href default ("https://host:port/tmf-api/partyManagement/v5/organization/" ++ ((rp.id default "ORG-ALPHA-001") as String)),
      name: rp.name default "AlphaConsult SIA"
    }
  }
else
  [
    {
      "@type": "RelatedPartyRefOrRelatedPartyRoleRef",
      role: "billReceiver",
      partyOrPartyRole: {
        "@type": "PartyRefOrPartyRoleRef",
        "@referredType": "Organization",
        id: "ORG-ALPHA-001",
        href: "https://host:port/tmf-api/partyManagement/v5/organization/ORG-ALPHA-001",
        name: "AlphaConsult SIA"
      }
    }
  ]
---
{
  "@type": "BillingAccount",
  id: generatedId,
  href: "https://host:port/tmf-api/accountManagement/v5/billingAccount/" ++ generatedId,
  description: payload.description default "MVP demo account linked to AlphaConsult SIA",
  ratingType: payload.ratingType default "postpaid",
  category: payload.category default "B2B enterprise",
  currencyCode: payload.currencyCode default "EUR",
  name: (payload.name default "AlphaConsult SIA Billing Account"),
  accountType: (payload.accountType default "Business"),
  state: (payload.state default "Active"),
  billStructure: (payload.billStructure default {
