        name: "Electronic"
      }
    ],
    cycleSpecification: cycleSpecification
  }),
  paymentPlan: (payload.paymentPlan default [
    {
      "@type": "PaymentPlan",
      priority: 1,
      status: "Effective",
      paymentFrequency: "monthly",
      planType: "regular",
      paymentMethod: paymentMethod
    }
  ]),
  defaultPaymentMethod: paymentMethod,
  relatedParty: normalizedRelatedParty
} as Object {encoding: "UTF-8", mediaType: "application/json"}

